<script setup>
import { computed, ref, watch } from 'vue'
import Icon from '../components/Icon.vue'
import MetricCard from '../components/MetricCard.vue'
import StatusBadge from '../components/StatusBadge.vue'
import EnvironmentCard from '../components/EnvironmentCard.vue'
import ResourceBars from '../components/ResourceBars.vue'
const props = defineProps({ envs: Array, snapshot: Object, retired: Array, canAdmin: Boolean, cols: Object })
const emit = defineEmits(['details', 'borrow', 'run', 'lease', 'navigate', 'maintenance', 'create', 'restore', 'timeline', 'export', 'events', 'batch-operate', 'col-toggle'])
// 视图与每页个数记住用户偏好；默认列表视图、每页 6 个（SSR 环境无 localStorage）
const localPref = key => { try { return localStorage.getItem(key) } catch { return null } }
const tab = ref('all'), arch = ref('all'), type = ref('all'), query = ref(''), view = ref(localPref('argus.envView') === 'grid' ? 'grid' : 'list'), page = ref(1), tag = ref('all')
const owner = ref('all'), location = ref('all'), version = ref('all'), sortBy = ref('default')
const batchSelected = ref([])
const pageSize = ref([6, 12, 24].includes(Number(localPref('argus.envPageSize'))) ? Number(localPref('argus.envPageSize')) : 6)
watch(view, v => { try { localStorage.setItem('argus.envView', v) } catch { /* 忽略存储失败 */ } })
watch(pageSize, n => { page.value = 1; try { localStorage.setItem('argus.envPageSize', String(n)) } catch { /* 忽略存储失败 */ } })
const colLabels = { owner: '负责人', version: '系统版本', location: '位置', tags: '标签', ip: 'IP' }
// 已移出环境未经 enrich，兜底从快照设备取 IP / 宿主机
const envIp = env => env.ip || [...new Set((env.deviceIds || []).map(id => props.snapshot.devices.find(d => d.id === id)?.ip).filter(Boolean))].join(', ')
const envHost = env => env.host || [...new Set((env.deviceIds || []).map(id => props.snapshot.devices.find(d => d.id === id)?.host).filter(Boolean))].join(', ')
function togglePage(checked) {
  const ids = paginated.value.map(e => e.id)
  batchSelected.value = checked ? [...new Set([...batchSelected.value, ...ids])] : batchSelected.value.filter(i => !ids.includes(i))
}
function toggleRow(id) { batchSelected.value = batchSelected.value.includes(id) ? batchSelected.value.filter(i => i !== id) : [...batchSelected.value, id] }
watch([tab, query], () => { batchSelected.value = [] })
const currentFilters = () => ({ includeRetired: tab.value === 'retired', arch: arch.value === 'all' ? '' : arch.value, type: type.value === 'all' ? '' : type.value, tag: tag.value === 'all' ? '' : tag.value, owner: owner.value === 'all' ? '' : owner.value, location: location.value === 'all' ? '' : location.value, version: version.value === 'all' ? '' : version.value, query: query.value.trim() })
const occupiedStates = ['running', 'leased']
const counts = computed(() => ({ all: props.envs.length, available: props.envs.filter(e => e.status === 'available').length, occupied: props.envs.filter(e => occupiedStates.includes(e.status)).length, unavailable: props.envs.filter(e => !['available', ...occupiedStates].includes(e.status)).length, retired: (props.retired || []).length }))
const tabs = [{ id: 'all', label: '全部环境' }, { id: 'available', label: '可借用' }, { id: 'occupied', label: '使用中' }, { id: 'unavailable', label: '维护 / 隔离' }, { id: 'retired', label: '已移出' }]
const allTags = computed(() => [...new Set(props.envs.flatMap(e => (e.tags || [])).filter(t => t !== 'ARM64' && t !== 'x86_64' && t !== '物理机' && t !== '虚拟机'))])
const ownerOptions = computed(() => [...new Set(props.envs.map(e => e.owner).filter(Boolean))])
const locationOptions = computed(() => [...new Set(props.envs.map(e => e.location).filter(Boolean))])
const versionOptions = computed(() => [...new Set(props.envs.map(e => e.version).filter(Boolean))])
const matchesTag = e => tag.value === 'all' || (e.tags || []).includes(tag.value)
const statusRank = e => ['isolated', 'maintenance', 'reconciling', 'cleaning', 'checking', 'running', 'leased', 'available'].indexOf(e.status)
const retiredList = computed(() => (props.retired || []).filter(e => `${e.id} ${e.name}`.toLowerCase().includes(query.value.trim().toLowerCase())))
const filtered = computed(() => {
  if (tab.value === 'retired') return retiredList.value
  const rows = props.envs.filter(e => (tab.value === 'all' || (tab.value === 'occupied' ? occupiedStates.includes(e.status) : tab.value === 'unavailable' ? !['available', ...occupiedStates].includes(e.status) : e.status === tab.value)) && (arch.value === 'all' || arch.value === e.arch) && (type.value === 'all' || type.value === e.type) && matchesTag(e) && (owner.value === 'all' || e.owner === owner.value) && (location.value === 'all' || e.location === location.value) && (version.value === 'all' || e.version === version.value) && `${e.id} ${e.name} ${e.description}`.toLowerCase().includes(query.value.trim().toLowerCase()))
  const sorters = { name: (a, b) => a.name.localeCompare(b.name, 'zh-CN'), devices: (a, b) => b.deviceIds.length - a.deviceIds.length, updated: (a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')), status: (a, b) => statusRank(a) - statusRank(b) }
  return sortBy.value === 'default' ? rows : [...rows].sort(sorters[sortBy.value])
})
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize.value)))
const paginated = computed(() => filtered.value.slice((page.value - 1) * pageSize.value, page.value * pageSize.value))
watch([tab, arch, type, query, tag, owner, location, version, sortBy], () => { page.value = 1 })
watch(pages, count => { page.value = Math.min(page.value, count) })
const attention = computed(() => [
  { count: props.snapshot.leases.filter(l => l.status === 'checking').length, title: '个借用待健康复核', icon: 'shield', tone: 'amber', target: 'leases' },
  { count: props.snapshot.runs.filter(r => r.status === 'reconciling').length, title: '个任务待对账', icon: 'clipboard', tone: 'amber', target: 'runs' },
  { count: props.snapshot.maintenance.filter(m => m.status === 'isolated').length, title: '个设备组已隔离', icon: 'alert', tone: 'red', target: 'maintenance' },
].filter(item => item.count))
function clear() { tab.value = 'all'; arch.value = 'all'; type.value = 'all'; query.value = ''; tag.value = 'all'; owner.value = 'all'; location.value = 'all'; version.value = 'all'; sortBy.value = 'default' }
const structure = computed(() => {
  const tally = (rows, key) => rows.reduce((acc, row) => { const k = key(row) || '未记录'; acc[k] = (acc[k] || 0) + 1; return acc }, {})
  const devices = props.snapshot.devices
  return {
    arch: tally(devices, d => d.arch), type: tally(devices, d => d.type),
    location: Object.entries(tally(devices, d => d.location)).sort((a, b) => b[1] - a[1]).slice(0, 4),
    tag: Object.entries(props.envs.reduce((acc, e) => { for (const t of (e.tags || [])) if (!['ARM64', 'x86_64', '物理机', '虚拟机'].includes(t)) acc[t] = (acc[t] || 0) + 1; return acc }, {})).sort((a, b) => b[1] - a[1]).slice(0, 6),
  }
})
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">RESOURCE WORKSPACE</div><h1>环境资源中心<span class="demo-tag">演示数据</span></h1><p>统一管理测试环境，让每一次执行都有据可循。</p></div><div class="heading-actions"><button v-if="canAdmin" class="button secondary" @click="emit('create')"><Icon name="plus" :size="17" />新增环境</button><button class="button secondary" @click="emit('export', currentFilters())"><Icon name="download" :size="17" />导出 CSV</button><button class="button secondary" @click="emit('navigate', 'leases')"><Icon name="clipboard" :size="17" />我的借用</button><button class="button primary" @click="emit('borrow')"><Icon name="plus" :size="18" />申请环境</button></div></div>
  <div class="metrics-grid environment-metrics"><MetricCard label="环境总数" :value="counts.all" detail="跨架构 · 统一资源视图" icon="server" spark /><MetricCard label="可借用" :value="counts.available" detail="全部关联设备均可用" icon="box" tone="green" spark /><MetricCard label="使用中" :value="counts.occupied" detail="人工借用与自动任务" icon="play" spark /><MetricCard label="维护 / 隔离" :value="counts.unavailable" detail="含待对账、清理与复核" icon="tool" tone="amber" spark /></div>
  <div class="environment-layout"><div class="environment-main"><section class="panel environment-browser" aria-label="环境列表">
    <div class="environment-toolbar"><div class="tabs" role="tablist" aria-label="环境状态"><button v-for="item in tabs" :key="item.id" role="tab" :aria-selected="tab === item.id" :class="{ active: tab === item.id }" @click="tab = item.id">{{ item.label }}<span>{{ counts[item.id] }}</span></button></div><div class="toolbar-tools"><label class="select-label per-page-select">每页<select v-model.number="pageSize" aria-label="每页显示个数"><option :value="6">6 个</option><option :value="12">12 个</option><option :value="24">24 个</option></select></label><div class="view-toggle" aria-label="视图切换"><button class="icon-button" :class="{ selected: view === 'grid' }" :aria-pressed="view === 'grid'" aria-label="卡片视图" @click="view = 'grid'"><Icon name="grid" :size="17" /></button><button class="icon-button" :class="{ selected: view === 'list' }" :aria-pressed="view === 'list'" aria-label="列表视图" @click="view = 'list'"><Icon name="list" :size="18" /></button></div></div></div>
    <div class="filter-bar"><label class="search-field"><Icon name="search" :size="17" /><input v-model="query" aria-label="搜索环境" placeholder="搜索环境名称或 ID" /><button v-if="query" class="icon-button" aria-label="清空环境搜索" @click="query = ''"><Icon name="close" :size="14" /></button></label><label class="select-label">架构<select v-model="arch" aria-label="筛选架构"><option value="all">全部架构</option><option>ARM64</option><option>x86_64</option></select></label><label class="select-label">类型<select v-model="type" aria-label="筛选类型"><option value="all">全部类型</option><option value="physical">物理机</option><option value="virtual">虚拟机</option></select></label><label class="select-label">标签<select v-model="tag" aria-label="筛选标签"><option value="all">全部标签</option><option v-for="t in allTags" :key="t" :value="t">{{ t }}</option></select></label><label class="select-label">负责人<select v-model="owner" aria-label="筛选负责人"><option value="all">全部负责人</option><option v-for="o in ownerOptions" :key="o" :value="o">{{ o }}</option></select></label><label class="select-label">位置<select v-model="location" aria-label="筛选位置"><option value="all">全部位置</option><option v-for="l in locationOptions" :key="l" :value="l">{{ l }}</option></select></label><label class="select-label">版本<select v-model="version" aria-label="筛选版本"><option value="all">全部版本</option><option v-for="v in versionOptions" :key="v" :value="v">{{ v }}</option></select></label><label class="select-label">排序<select v-model="sortBy" aria-label="排序方式"><option value="default">默认排序</option><option value="name">按名称</option><option value="devices">按设备数</option><option value="status">按状态</option><option value="updated">按最近更新</option></select></label></div>
    <div v-if="tab === 'retired'" class="table-scroll"><table class="data-table"><thead><tr><th>环境 / ID</th><th>架构 / 类型</th><th>IP</th><th>负责人</th><th>移出时间</th><th>操作</th></tr></thead><tbody><tr v-for="env in paginated" :key="env.id"><td><button class="plain-title" @click="emit('timeline', env)">{{ env.name }}</button><small class="mono">{{ env.id }}</small></td><td>{{ env.arch }}<small>{{ env.type === 'physical' ? '物理机' : '虚拟机' }}</small><small v-if="env.type === 'virtual' && envHost(env)" class="mono">宿主机 {{ envHost(env) }}</small></td><td class="mono">{{ envIp(env) || '未记录' }}</td><td>{{ env.owner || '未记录' }}</td><td class="mono">{{ (env.updatedAt || '').slice(0, 16).replace('T', ' ') }}</td><td><div class="table-actions"><button class="text-button" @click="emit('timeline', env)">查看历史</button><button v-if="canAdmin" class="text-button" @click="emit('restore', env)">恢复入池</button></div></td></tr></tbody></table><div v-if="!filtered.length" class="empty-state"><Icon name="box" :size="34" /><p>没有已移出的环境</p></div></div>
    <div v-else-if="filtered.length && view === 'grid'" class="environment-grid"><EnvironmentCard v-for="env in paginated" :key="env.id" :env="env" @details="emit('details', $event)" @borrow="emit('borrow', $event)" @run="emit('run', $event)" @lease="emit('lease', $event)" @maintenance="emit('maintenance', $event)" /></div>
    <div v-else-if="filtered.length" class="table-scroll environment-list"><table class="data-table"><thead><tr><th v-if="canAdmin" class="col-check"><input type="checkbox" :aria-label="`全选本页`" :checked="paginated.length && paginated.every(e => batchSelected.includes(e.id))" @change="togglePage($event.target.checked)" /></th><th>环境 / ID</th><th v-if="cols?.ip !== false">IP</th><th v-if="cols?.arch !== false">架构 / 类型</th><th v-if="cols?.owner === true">负责人</th><th v-if="cols?.version === true">系统版本</th><th v-if="cols?.location === true">位置</th><th v-if="cols?.devices !== false">设备</th><th v-if="cols?.status !== false">状态</th><th>操作</th></tr></thead><tbody><tr v-for="env in paginated" :key="env.id" :style="batchSelected.includes(env.id) ? 'background:var(--blue-soft)' : undefined"><td v-if="canAdmin" class="col-check"><input type="checkbox" :aria-label="`选择 ${env.name}`" :checked="batchSelected.includes(env.id)" @change="toggleRow(env.id)" /></td><td><button class="plain-title" @click="emit('details', env)">{{ env.name }}</button><small class="mono">{{ env.id }}</small><div v-if="cols?.tags === true" class="env-tags"><span v-for="t in (env.tags || []).filter(t => !['ARM64','x86_64','物理机','虚拟机'].includes(t))" :key="t" class="badge tone-muted">{{ t }}</span></div></td><td v-if="cols?.ip !== false" class="mono">{{ envIp(env) || '未记录' }}</td><td v-if="cols?.arch !== false">{{ env.arch }}<small>{{ env.type === 'physical' ? '物理机' : '虚拟机' }}</small><small v-if="env.type === 'virtual' && envHost(env)" class="mono">宿主机 {{ envHost(env) }}</small></td><td v-if="cols?.owner === true">{{ env.owner || '未记录' }}</td><td v-if="cols?.version === true">{{ env.version || '未记录' }}</td><td v-if="cols?.location === true">{{ env.location || '未记录' }}</td><td v-if="cols?.devices !== false">{{ env.deviceIds.length }} 台</td><td v-if="cols?.status !== false"><StatusBadge :status="env.status" /></td><td><button class="text-button" @click="env.status === 'available' ? emit('borrow', env) : emit('details', env)">{{ env.status === 'available' ? '申请借用' : '查看详情' }}</button></td></tr></tbody></table></div>
    <div v-if="canAdmin && batchSelected.length" class="batch-bar"><span>已选 {{ batchSelected.length }} 个环境</span><button class="button danger small" @click="emit('batch-operate', { kind: 'retire', ids: [...batchSelected] })">批量移出</button><button class="button secondary small" @click="batchSelected = []">取消选择</button></div>
    <div v-if="canAdmin" class="cols-config"><label v-for="(enabled, key) in cols" :key="key" v-show="!['status', 'devices', 'arch'].includes(key)" class="checkbox-label"><input type="checkbox" :checked="enabled" @change="emit('col-toggle', key)" />{{ colLabels[key] || key }}</label></div>
    <div v-else class="empty-state"><Icon name="search" :size="38" /><h3>没有找到匹配的环境</h3><p>调整搜索词或筛选条件，看看其他资源。</p><button class="button secondary small" @click="clear">清空筛选</button></div>
    <div class="pagination"><span>共 {{ filtered.length }} 个环境 · 每页 {{ pageSize }} 个</span><div><button class="icon-button" aria-label="上一页" :disabled="page <= 1" @click="page--"><Icon name="chevron" :size="16" class="rotate" /></button><button v-for="n in pages" :key="n" class="page-button" :class="{ active: page === n }" :aria-label="`第 ${n} 页`" :aria-current="page === n ? 'page' : undefined" @click="page = n">{{ n }}</button><button class="icon-button" aria-label="下一页" :disabled="page >= pages" @click="page++"><Icon name="chevron" :size="16" /></button></div></div>
  </section><section class="panel execution-strip"><span><Icon name="flow" />当前执行</span><button @click="emit('navigate', 'runs')">执行中<strong>{{ snapshot.runs.filter(r => r.status === 'running').length }}</strong><i class="dot blue" /></button><button @click="emit('navigate', 'runs')">待清理<strong>{{ snapshot.runs.filter(r => r.status === 'cleaning').length }}</strong><i class="dot amber" /></button><button class="text-button" @click="emit('navigate', 'runs')">执行记录<Icon name="arrow" :size="16" /></button></section></div>
    <aside class="right-rail"><section class="panel rail-panel"><div class="panel-heading"><h2>设备占用分布</h2><Icon name="chart" :size="17" /></div><ResourceBars :devices="snapshot.devices" /><div class="subtle-note">按唯一设备统计，共 {{ snapshot.devices.length }} 台</div></section>
      <section class="panel rail-panel"><div class="panel-heading"><h2>资源结构分布</h2><Icon name="grid" :size="16" /></div><div class="structure-rows"><div v-for="(count, key) in structure.arch" :key="key" class="structure-row"><span>{{ key }}</span><strong class="mono">{{ count }} 台</strong></div><div v-for="(count, key) in structure.type" :key="'t' + key" class="structure-row"><span>{{ key === 'physical' ? '物理机' : '虚拟机' }}</span><strong class="mono">{{ count }} 台</strong></div></div><div v-if="structure.tag.length" class="subtle-note structure-tags">自定义标签：<span v-for="[t, c] in structure.tag" :key="t" class="badge tone-muted">{{ t }} × {{ c }}</span></div><div v-if="structure.location.length" class="subtle-note">位置 TOP：{{ structure.location.map(([l, c]) => `${l} ${c} 台`).join(' · ') }}</div></section>
      <section class="panel rail-panel"><div class="panel-heading"><h2>待处理事项</h2><span class="count-pill">{{ attention.reduce((s, i) => s + i.count, 0) }}</span></div><button v-for="item in attention" :key="item.title" class="attention-item" @click="emit('navigate', item.target)"><span class="soft-icon" :class="`tone-${item.tone}`"><Icon :name="item.icon" :size="19" /></span><span><strong :class="`color-${item.tone}`">{{ item.count }}</strong> {{ item.title }}</span><Icon name="chevron" :size="16" /></button><p v-if="!attention.length" class="subtle-note">暂无待处理事项</p><div class="resource-rule"><Icon name="lock" :size="17" /><div><strong>共享设备独占锁定</strong><p>同一台设备同一时间仅允许一项占用。</p></div></div></section>
      <section class="panel rail-panel"><div class="panel-heading"><h2>最近动态</h2><button class="text-button" @click="emit('events')"><Icon name="list" :size="14" />全部事件</button></div><ol class="activity-list"><li v-for="(item, i) in snapshot.activities.slice(0, 4)" :key="i"><i class="dot" :class="item.tone" /><span class="mono">{{ item.time }}</span><p>{{ item.text }}</p></li></ol></section>
    </aside>
  </div>
</template>
